-- E&P Learning: M2 Earth and Space Science knowledge graph (standard ว 3.2).
-- Official Thai Basic Education Core Curriculum B.E. 2551, revised B.E. 2560.
-- Seeds ten M2 indicators. No school or learner records are created.
begin;
do $$ begin if not exists(select 1 from public.learning_subjects s join public.learning_curricula c on c.code='TH-SCI-M1-M6' join public.learning_education_systems es on es.id=c.education_system_id join public.learning_grade_levels g on g.curriculum_id=c.id and g.code='M2' where s.code='SCI' and es.code='TH_BASIC' and s.status='active' and c.status='active' and g.status='active') then raise exception 'Active SCI M2 curriculum is required.'; end if; end $$;
insert into public.learning_topics(skill_id,code,name,description,sequence_no,status) select sk.id,t.code,t.name,t.description,t.seq,'active' from public.learning_subjects s join public.learning_skills sk on sk.subject_id=s.id join (values ('EARTH','M2-ENERGY-SOURCES','Energy Resources','M2 Earth and Space Science topic aligned to standard ว 3.2.',1),('EARTH','M2-EARTH-STRUCTURE','Earth Structure','M2 Earth and Space Science topic aligned to standard ว 3.2.',2),('EARTH','M2-SURFACE-PROCESSES','Surface Processes and Soil','M2 Earth and Space Science topic aligned to standard ว 3.2.',3),('EARTH','M2-WATER-RESOURCES','Water Resources','M2 Earth and Space Science topic aligned to standard ว 3.2.',4),('EARTH','M2-HAZARDS','Geological Hazards','M2 Earth and Space Science topic aligned to standard ว 3.2.',5)) as t(skill_code,code,name,description,seq) on true where s.code='SCI' on conflict(skill_id,code) do update set name=excluded.name,description=excluded.description,sequence_no=excluded.sequence_no,status='active',updated_at=now();
insert into public.learning_objectives(topic_id,code,name,description,sequence_no,status) select tp.id,o.code,o.name,o.description,o.seq,'active' from public.learning_subjects s join public.learning_skills sk on sk.subject_id=s.id join (values ('M2-ENERGY-SOURCES','M2-S3_2-01','Compare fossil fuels','Compare formation, properties, uses and impacts of fossil fuels using collected information.',1),('M2-ENERGY-SOURCES','M2-S3_2-02','Use fossil fuels responsibly','Explain impacts of fossil-fuel use and propose responsible use.',2),('M2-ENERGY-SOURCES','M2-S3_2-03','Compare renewable energy options','Compare benefits and limitations of renewable energy and propose suitable local options.',3),('M2-EARTH-STRUCTURE','M2-S3_2-04','Model Earth''s internal structure','Create a model of Earth''s internal structure based on chemical composition.',4),('M2-SURFACE-PROCESSES','M2-S3_2-05','Explain weathering, erosion and deposition','Explain weathering, erosion and deposition and their effects on landforms.',5),('M2-SURFACE-PROCESSES','M2-S3_2-06','Explain soil profiles and soil formation','Explain soil horizons, soil formation and factors affecting soil properties.',6),('M2-SURFACE-PROCESSES','M2-S3_2-07','Measure soil properties','Use suitable tools to investigate selected soil properties and interpret results.',7),('M2-WATER-RESOURCES','M2-S3_2-08','Explain surface water and groundwater','Model the factors and processes that form surface-water and groundwater sources.',8),('M2-WATER-RESOURCES','M2-S3_2-09','Plan sustainable local water use','Model water use and propose sustainable local water-management practices.',9),('M2-HAZARDS','M2-S3_2-10','Model geological and water-related hazards','Model causes and impacts of floods, coastal erosion, landslides, sinkholes and land subsidence.',10)) as o(topic_code,code,name,description,seq) on true join public.learning_topics tp on tp.skill_id=sk.id and tp.code=o.topic_code where s.code='SCI' and sk.code='EARTH' on conflict(topic_id,code) do update set name=excluded.name,description=excluded.description,sequence_no=excluded.sequence_no,status='active',updated_at=now();
insert into public.learning_objective_alignments(objective_id,curriculum_id,grade_level_id,sequence_no,required,notes) select ob.id,c.id,g.id,a.seq,true,'Thailand Basic Education Core Curriculum B.E. 2551 (2008), revised B.E. 2560 (2017); official indicator '||a.indicator||'.' from (values ('M2-S3_2-01',1,'ว 3.2 ม.2/1'),('M2-S3_2-02',2,'ว 3.2 ม.2/2'),('M2-S3_2-03',3,'ว 3.2 ม.2/3'),('M2-S3_2-04',4,'ว 3.2 ม.2/4'),('M2-S3_2-05',5,'ว 3.2 ม.2/5'),('M2-S3_2-06',6,'ว 3.2 ม.2/6'),('M2-S3_2-07',7,'ว 3.2 ม.2/7'),('M2-S3_2-08',8,'ว 3.2 ม.2/8'),('M2-S3_2-09',9,'ว 3.2 ม.2/9'),('M2-S3_2-10',10,'ว 3.2 ม.2/10')) as a(code,seq,indicator) join public.learning_objectives ob on ob.code=a.code join public.learning_topics tp on tp.id=ob.topic_id join public.learning_skills sk on sk.id=tp.skill_id join public.learning_subjects s on s.id=sk.subject_id and s.code='SCI' join public.learning_curricula c on c.code='TH-SCI-M1-M6' join public.learning_grade_levels g on g.curriculum_id=c.id and g.code='M2' on conflict(objective_id,curriculum_id,grade_level_id) do update set sequence_no=excluded.sequence_no,required=excluded.required,notes=excluded.notes,updated_at=now();
commit;
